var q = New Query(
    "SELECT Producer, SUM(Weight) AS TotalWeight " +
    "FROM Catalog.Products GROUP BY Producer HAVING SUM(Weight) > 50");
var sel = q.Execute().Select();
while (sel.Next())
    Message(sel.Producer + " -> " + sel.TotalWeight);

